package io.knowledgebrain.learning;
import java.util.*;
import java.time.Clock;
import jakarta.servlet.http.Cookie;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;
import org.junit.jupiter.api.*;
import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;
class RoadmapApiTest {
 RoadmapStore store;SpaceAuthorizationClient authority;RoadmapController api;UUID space,actor,id;
 @BeforeEach void setup(){store=mock(RoadmapStore.class);authority=mock(SpaceAuthorizationClient.class);api=new RoadmapController(store,authority,new SimpleMeterRegistry(),"https://localhost:8443");var ids=new UuidV7(Clock.systemUTC());space=ids.next();actor=ids.next();id=ids.next();when(authority.authorize(eq(space),any(),anyBoolean(),anyString())).thenReturn(actor);}
 MockHttpServletRequest r(String method){var r=new MockHttpServletRequest(method,"/api/spaces/"+space+"/roadmaps");r.setSecure(true);r.setCookies(new Cookie("__Host-brain_guest","a".repeat(43)));r.addHeader("Origin","https://localhost:8443");r.setContentType("application/json");return r;}
 @Test void freshAuthorityPrecedesEveryCanonicalListAndDenialNeverReadsRows(){when(store.list(space,null,20)).thenReturn(new RoadmapStore.Page(List.of(),null));assertEquals("no-store",api.list(space.toString(),r("GET")).getHeaders().getCacheControl());api.list(space.toString(),r("GET"));var order=inOrder(authority,store);for(int n=0;n<2;n++){order.verify(authority).authorize(eq(space),eq("a".repeat(43)),eq(false),anyString());order.verify(store).list(space,null,20);}reset(store);when(authority.authorize(eq(space),any(),anyBoolean(),anyString())).thenThrow(new ResponseStatusException(HttpStatus.NOT_FOUND));assertThrows(ResponseStatusException.class,()->api.list(space.toString(),r("GET")));verifyNoInteractions(store);}
 @Test void malformedQueriesGetBodyAndUppercaseIdsFailBeforeAuthority(){for(String limit:List.of("0","101","01","999999999999999999999")){var req=r("GET");req.addParameter("limit",limit);assertThrows(ResponseStatusException.class,()->api.list(space.toString(),req));}var duplicate=r("GET");duplicate.addParameter("limit","1","2");assertThrows(ResponseStatusException.class,()->api.list(space.toString(),duplicate));var body=r("GET");body.setContent(new byte[]{1});assertThrows(ResponseStatusException.class,()->api.get(space.toString(),id.toString(),body));assertThrows(ResponseStatusException.class,()->api.list("00000000-0000-4000-8000-000000000001",r("GET")));verifyNoInteractions(authority,store);}
 @Test void strongRoadmapVersionOriginAndStrictJsonBoundariesProtectWrites()throws Exception{for(String tag:List.of("\"1\"","\"cl1\"","W/\"rm1\"","\"rm0\"","\"rm9223372036854775808\"")){var req=r("PUT");req.addHeader("If-Match",tag);req.setContent("{\"title\":\"A\",\"description\":\"\"}".getBytes());assertThrows(ResponseStatusException.class,()->api.metadata(space.toString(),id.toString(),req));}var missing=r("PUT");assertEquals(428,assertThrows(ResponseStatusException.class,()->api.metadata(space.toString(),id.toString(),missing)).getStatusCode().value());for(String json:List.of("{}","{\"title\":\"A\",\"title\":\"B\",\"description\":\"\"}","{\"title\":\"A\",\"description\":\"\"} {}","{\"title\":\"A\",\"description\":\"\",\"actorId\":\"spoof\"}")){var req=r("POST");req.setContent(json.getBytes());assertThrows(ResponseStatusException.class,()->api.create(space.toString(),req));}var origin=r("POST");origin.removeHeader("Origin");origin.addHeader("Origin","https://foreign.invalid");assertEquals(403,assertThrows(ResponseStatusException.class,()->api.create(space.toString(),origin)).getStatusCode().value());verifyNoInteractions(store);}
 @Test void serverOnlyAssignsDraftIdsAndRejectsUnknownGraphShapes()throws Exception{for(String json:List.of("{\"nodes\":{},\"edges\":[]}","{\"nodes\":[{\"key\":\"new:a\",\"title\":\"A\",\"description\":\"\",\"nodeId\":\"client\"}],\"edges\":[]}","{\"nodes\":[],\"edges\":[],\"visibility\":\"PUBLIC\"}")){var req=r("PUT");req.addHeader("If-Match","\"rm1\"");req.setContent(json.getBytes());assertThrows(ResponseStatusException.class,()->api.graph(space.toString(),id.toString(),req));}verifyNoInteractions(store);}
 @Test void httpLayerReturnsVersionAndMalformedErrorsWithoutErrorDispatch()throws Exception{var mvc=org.springframework.test.web.servlet.setup.MockMvcBuilders.standaloneSetup(api).setControllerAdvice(new RoadmapErrors()).build();String path="/api/spaces/"+space+"/roadmaps/"+id+"/graph";mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.put(path).secure(true).cookie(new Cookie("__Host-brain_guest","a".repeat(43))).header("Origin","https://localhost:8443").contentType("application/json").content("{\"nodes\":[],\"edges\":[]}")).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().is(428)).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.header().string("Cache-Control","no-store"));mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.put(path).secure(true).cookie(new Cookie("__Host-brain_guest","a".repeat(43))).header("Origin","https://localhost:8443").header("If-Match","\"rm1\"").contentType("application/json").content("{}")).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isBadRequest());verifyNoInteractions(store);}
}
